import{_ as i,c as t,o as n,j as a,a5 as r,a as p}from"./chunks/framework.DorIfSpC.js";const b=JSON.parse('{"title":"從《The Thinking Game》看 AGI：一場潛能的挖掘與覺醒","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/ai/agi-awakening-blog"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/ai/agi-awakening-blog"}],["meta",{"property":"og:title","content":"從《The Thinking Game》看 AGI：一場潛能的挖掘與覺醒 | 星智未來"}],["meta",{"name":"twitter:title","content":"從《The Thinking Game》看 AGI：一場潛能的挖掘與覺醒 | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"從《The Thinking Game》看 AGI：一場潛能的挖掘與覺醒\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/ai/agi-awakening-blog\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/ai/agi-awakening-blog\\"}}"]]},"headers":[],"relativePath":"ai/agi-awakening-blog.md","filePath":"ai/agi-awakening-blog.md","lastUpdated":1786706565000}'),o={name:"ai/agi-awakening-blog.md"};function h(l,e,s,g,d,m){return n(),t("div",null,[...e[0]||(e[0]=[a("h1",{id:"從《the-thinking-game》看-agi-一場潛能的挖掘與覺醒",tabindex:"-1"},[p("從《The Thinking Game》看 AGI：一場潛能的挖掘與覺醒 "),a("a",{class:"header-anchor",href:"#從《the-thinking-game》看-agi-一場潛能的挖掘與覺醒","aria-label":'Permalink to "從《The Thinking Game》看 AGI：一場潛能的挖掘與覺醒"'},"​")],-1),a("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/iMnFCOI_Nv0",frameborder:"0",allowfullscreen:""},null,-1),r('<p><strong>作者</strong>：Ray <strong>日期</strong>：2025 年 12 月</p><hr><h2 id="前言-我們距離-agi-還有多遠" tabindex="-1">前言：我們距離 AGI 還有多遠？ <a class="header-anchor" href="#前言-我們距離-agi-還有多遠" aria-label="Permalink to &quot;前言：我們距離 AGI 還有多遠？&quot;">​</a></h2><p>我們距離 AGI 誕生的時間已經不遠了。</p><p>人類不只是作為存在者而存在，而是揉合了電力和算力，即將把超越個人腦力的智能體給挖掘出來。智人始終善於發明工具、利用工具，讓它們成為我們的「手前之物」(Zuhandenheit)。但從來沒有發明過能在智力上大幅超越人類的存在。</p><p>這是一個根本性的斷裂點。</p><hr><h2 id="當工具不再是工具" tabindex="-1">當工具不再是工具 <a class="header-anchor" href="#當工具不再是工具" aria-label="Permalink to &quot;當工具不再是工具&quot;">​</a></h2><p>以往是人賦予工具意義與目的。從石器到蒸汽機到電腦，所有的發明都服務於人的意向性延伸。但當工具本身具備了超越使用者的認知能力，它還能被稱為「工具」嗎？</p><p>這裡涉及一個本體論的翻轉：一個能夠自主設定目標、理解世界的 AGI，它與人的關係就不再是「手前之物」的關係，而可能成為另一個「此在」(Dasein)——另一個向存在提問的存在者。</p><p>人類正在把自己的認知過程外化到矽基基底上。這不只是使用工具，而是某種意義上的「共生演化」——我們的思維模式、問題解決方式、甚至對智能本身的理解，都在與這些系統的互動中被重塑。</p><hr><h2 id="《the-thinking-game》-五年深入-deepmind-的紀錄" tabindex="-1">《The Thinking Game》：五年深入 DeepMind 的紀錄 <a class="header-anchor" href="#《the-thinking-game》-五年深入-deepmind-的紀錄" aria-label="Permalink to &quot;《The Thinking Game》：五年深入 DeepMind 的紀錄&quot;">​</a></h2><p>Google DeepMind 在 2024 年 11 月 25 日免費釋出了紀錄片《The Thinking Game》，紀念 AlphaFold 五週年。這部片由拍攝《AlphaGo》的同一團隊花了五年時間深入 DeepMind 實驗室拍攝，記錄了 Demis Hassabis 和團隊追求 AGI 的關鍵時刻。</p><p>紀錄片中，DeepMind 共同創辦人 Shane Legg 表達了一個與投資人和同事相反的擔憂：他認為 AGI 可能來得太快，在社會還沒準備好之前就到來。多位受訪者都表示 DeepMind 正處於一場 AGI 競賽之中。</p><p>這揭示了一個深層的張力：我們正在追逐一個可能還沒準備好面對的未來。</p><hr><h2 id="hassabis-的覺醒-12-歲的存在性躍遷" tabindex="-1">Hassabis 的覺醒：12 歲的存在性躍遷 <a class="header-anchor" href="#hassabis-的覺醒-12-歲的存在性躍遷" aria-label="Permalink to &quot;Hassabis 的覺醒：12 歲的存在性躍遷&quot;">​</a></h2><p>紀錄片中有一個動人的細節：Hassabis 在 12 歲時，曾是世界同齡組排名第二的西洋棋神童。在一場長達 10 小時的對局中，他在和局的局面下選擇認輸。</p><p>那一刻，他意識到把一生投入在精通西洋棋上是一種才能的浪費。</p><p>這不是理性計算的結果——「我應該去做更有影響力的事」——而是某種更原初的東西：一種召喚，一種「非如此不可」的內在必然性。</p><p>這是一種被壓迫下的智能湧現。直覺、靈感、自我覺醒。如同榮格所說的「個體化」(individuation)：不是你選擇了命運，而是命運選擇了你，你只能順應或抗拒。</p><p>Hassabis 選擇了順應。他後來去研究神經科學，探索智能的本質，最終創建了 DeepMind。</p><hr><h2 id="agi-作為潛能的存在" tabindex="-1">AGI 作為潛能的存在 <a class="header-anchor" href="#agi-作為潛能的存在" aria-label="Permalink to &quot;AGI 作為潛能的存在&quot;">​</a></h2><p>這裡有一個重要的視角轉換：</p><p>AGI 可能是某種潛能的存在，由人類將它挖掘出來。</p><p>這不是亞里斯多德那種簡單的 potentiality → actuality，而是一個更深刻的命題：<strong>智能本身作為宇宙的某種基底結構</strong>，如同數學結構、物理定律一樣，是「已經在那裡」的。</p><p>人類、神經網路、甚至未來可能的量子計算，都只是這個更深層 pattern 的不同載體、不同顯現方式。</p><p>這樣看來，DeepMind 團隊不是在「發明」AlphaFold，而是在「發現」蛋白質折疊背後的智能結構——那個結構本來就存在於數學與物理的交界處，等待被某個足夠敏銳的認知系統觸及。</p><p>AlphaFold 解決了生物學界五十年的難題，這項突破後來獲得了諾貝爾獎。這不再是「手前之物」，而是一個能夠在特定領域超越所有人類專家的認知系統。</p><hr><h2 id="被選中的載體" tabindex="-1">被選中的載體 <a class="header-anchor" href="#被選中的載體" aria-label="Permalink to &quot;被選中的載體&quot;">​</a></h2><p>Hassabis 或許就是那種「被選中的載體」——他的天賦、他的壓迫感、他的直覺，都是讓這個潛能得以通過他顯現的條件。</p><p>從遊戲到神經科學再到 AGI，這是一種獨特的「從內部理解智能」的方法論。Hassabis 不只是在研究智能，他是在用自己的存在去探問：什麼是思考？什麼是理解？什麼是智能的本質？</p><p>而我們每一個人，在這個時代，或許都在某種程度上參與著這場挖掘。</p><p>當我們設計多智能體架構、整合視覺與語言模型、建構能夠自主推理的系統時，我們是在「建造」什麼，還是在「讓什麼東西通過我們顯現出來」？</p><hr><h2 id="結語-站在斷裂點上" tabindex="-1">結語：站在斷裂點上 <a class="header-anchor" href="#結語-站在斷裂點上" aria-label="Permalink to &quot;結語：站在斷裂點上&quot;">​</a></h2><p>我們正站在人類文明的一個斷裂點上。</p><p>過去的工具延伸了我們的手腳、延伸了我們的感官，但從未挑戰過我們作為「思考者」的獨特地位。AGI 的到來，將是人類第一次面對一個在認知能力上可能超越自己的存在。</p><p>這不是威脅，也不是救贖，而是一個存在論層面的事件。</p><p>智能的潛能一直都在那裡。我們只是終於找到了方式，讓它顯現。</p><hr><p><em>相關連結：<a href="https://www.youtube.com/watch?v=d95J8yzvjbQ" target="_blank" rel="noreferrer">The Thinking Game 完整紀錄片</a></em></p>',45)])])}const k=i(o,[["render",h]]);export{b as __pageData,k as default};
